questions.solution:
public class WeatherCheck {
    public static void main(String[] args) {
        int temperature = 28;
        if (temperature > 35) {
            System.out.println("Hot");
        } else if (temperature >= 20) {
            System.out.println("Warm");
        } else {
            System.out.println("Cold");
        }
    }
}

